<?php $normal=count(array_filter($epis,fn($e)=>$e['quantidade_estoque']>$e['estoque_minimo'])); $zero=count(array_filter($epis,fn($e)=>$e['quantidade_estoque']==0)); ?>
<div class="stats-grid three"><article class="stat"><span>Estoque normal</span><strong><?= $normal ?></strong><small>Tipos de equipamento</small></article><article class="stat"><span>Estoque baixo</span><strong><?= count($epis)-$normal-$zero ?></strong><small>No mínimo ou abaixo</small></article><article class="stat"><span>Sem estoque</span><strong><?= $zero ?></strong><small>Precisam de reposição</small></article></div>
<section class="card analytics-card"><div class="section-heading"><div><h2>Estoque de EPIs</h2><p>Quantidade disponível de cada equipamento no sistema.</p></div><span class="chart-symbol" aria-hidden="true">▥</span></div><?php $chartItems=array_map(fn($epi)=>['label'=>$epi['nome_epi'],'value'=>(int)$epi['quantidade_estoque']],$epis); require __DIR__.'/vertical-chart.php'; ?></section>
<section class="card"><div class="section-heading"><h2>Equipamentos cadastrados</h2><a class="button" href="fazerpedidos.php">＋ Pedir reposição</a></div><div class="table-wrap"><table><thead><tr><th>EPI</th><th>Código / CA</th><th>Disponível</th><th>Mínimo</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php foreach($epis as $epi): $zero=$epi['quantidade_estoque']==0; $low=$epi['quantidade_estoque']<=$epi['estoque_minimo']; ?><tr><td><strong><?= e($epi['nome_epi']) ?></strong><small><?= e($epi['descricao']) ?></small></td><td><?= e($epi['codigo']) ?><small>CA <?= e($epi['ca']?:'não informado') ?></small></td><td><?= (int)$epi['quantidade_estoque'] ?></td><td><?= (int)$epi['estoque_minimo'] ?></td><td><span class="badge <?= $zero?'danger':($low?'warning':'success') ?>"><?= $zero?'Sem estoque':($low?'Estoque baixo':'Normal') ?></span></td><td><a href="fazerpedidos.php?id_epi=<?= (int)$epi['id_epi'] ?>">Repor →</a></td></tr><?php endforeach; if(!$epis): ?><tr><td colspan="6" class="empty">Nenhum EPI cadastrado.</td></tr><?php endif ?></tbody></table></div></section>
